addon.translation = {
-- d580a703 English: Enhancement (Icy Veins)
-- Context: Name of a Built In rotation for TBC Shaman, Enhancement spec, based on an Icy Veins
--     guide; a trailing site name in parentheses.
[1] = "Verstärkung (Icy Veins)",
-- a97cd0b7 English: Melee Enhancement from level 1 to 70, and the default for any Shaman no other
--     premade fits. Pulls with Lightning Bolt from range, interrupts with Earth Shock, drops Fire
--     Nova and Magma Totems on three or more nearby enemies, then Stormstrike, Earth Shock while
--     Stormstrike's debuff is up, Flame Shock on a target that will live, Earth Shock on cooldown,
--     and Lightning Bolt while the target is out of reach. Separate reminders: weapon imbues, Water
--     or Lightning Shield, Strength of Earth, Windfury (group) or Grace of Air (solo), Searing on
--     long fights, water totems, Shamanistic Rage, Bloodlust/Heroism on bosses, Stoneclaw and Earth
--     Elemental when solo. Fire Elemental is an optional step that starts off. Totem placement,
--     Ghost Wolf and healing stay with you.
[2] = "Verstärkung im Nahkampf von Stufe 1 bis 70 und der Standard für jeden Schamanen, zu dem keine andere integrierte Rotation passt. Zieht mit Blitzschlag aus der Distanz, unterbricht mit Erdschock, setzt bei drei oder mehr nahen Gegnern Totem der Feuernova und Totem des glühenden Magmas, dann Sturmschlag, Erdschock, solange der Schwächungszauber von Sturmschlag aktiv ist, Flammenschock auf ein Ziel, das lange genug lebt, Erdschock bei Abklingzeit-Ende und Blitzschlag, solange das Ziel außer Reichweite ist. Eigene Erinnerungen: Waffenverzauberungen, Wasser- oder Blitzschlagschild, Totem der Erdstärke, Totem des Windzorns (Gruppe) oder Totem der luftgleichen Anmut (solo), Totem der Verbrennung bei langen Kämpfen, Wassertotems, Schamanistische Wut, Kampfrausch/Heldentum bei Bossen, Totem der Steinklaue und Totem des Erdelementars beim Solospiel. Totem des Feuerelementars ist ein optionaler Schritt, der deaktiviert beginnt. Totemplatzierung, Geisterwolf und Heilung bleiben Ihnen überlassen.",
-- f2b68c6d English: Enhancement (Wowhead & simulator)
[3] = "Verstärkung (Wowhead & Simulation)",
-- 1ec4e078 English: The level-70 raid model for totem twisting, an alternative to the recommended
--     Icy Veins Enhancement premade, off by default: enable it and disable that one, or raise its
--     priority. Stormstrike, a Fire Nova Totem weave, Flame Shock whenever it has fallen off, and
--     Earth Shock as the main shock, with Lightning Bolt only out of reach. Reminders twist
--     Windfury and Grace of Air Totems, keep Searing down, use Shamanistic Rage when mana runs low,
--     and share the Icy Veins variant's imbue, shield and totem upkeep.
[4] = "Das Schlachtzugsmodell für Stufe 70 zum Totem-Twisting, eine Alternative zur empfohlenen integrierten Verstärkungsrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Sturmschlag, eingewobenes Totem der Feuernova, Flammenschock, sobald er ausgelaufen ist, und Erdschock als Hauptschock, Blitzschlag nur außer Reichweite. Die Erinnerungen wechseln (Twisting) zwischen Totem des Windzorns und Totem der luftgleichen Anmut, halten das Totem der Verbrennung aufrecht, nutzen Schamanistische Wut bei knappem Mana und teilen die Pflege von Waffenverzauberung, Schild und Totems mit der Icy-Veins-Variante.",
-- 0dc1ed9b English: Elemental (Icy Veins & simulator)
[5] = "Elementar (Icy Veins & Simulation)",
-- c334526c English: Caster Elemental for the Elemental talent tree. Lightning Bolt is the filler;
--     Chain Lightning goes out with Elemental Mastery, on Clearcasting while you have 40% mana, or
--     freely above 80%; Flame Shock only while moving; Earth Shock interrupts; Fire Nova, Chain
--     Lightning and Magma for packs. Before Chain Lightning a target in melee is left to
--     auto-attack to save mana. Reminders: Water or Lightning Shield, a weapon imbue, Totem of
--     Wrath (or Searing on long fights), Wrath of Air, Mana Spring, Totemic Call after the fight,
--     Elemental Mastery and Bloodlust/Heroism.
[6] = "Elementar-Zauberwirker für den Talentbaum Elementar. Blitzschlag ist der Füller; Kettenblitzschlag kommt mit Elementarbeherrschung, bei Freizaubern, solange Sie 40 % Mana haben, oder beliebig über 80 %; Flammenschock nur in Bewegung; Erdschock unterbricht; Feuernova, Kettenblitzschlag und Totem des glühenden Magmas für Gruppen von Gegnern. Vor Kettenblitzschlag wird ein Ziel im Nahkampf dem automatischen Angriff überlassen, um Mana zu sparen. Erinnerungen: Wasser- oder Blitzschlagschild, eine Waffenverzauberung, Totem des Ingrimms (oder Totem der Verbrennung bei langen Kämpfen), Totem des stürmischen Zorns, Totem der Manaquelle, Ruf der Totems nach dem Kampf, Elementarbeherrschung und Kampfrausch/Heldentum.",
-- 6c2dcf2e English: Elemental (Wowhead)
-- Context: Name of a Built In rotation for TBC Shaman, Elemental spec, based on a Wowhead guide;
--     the site name is in parentheses.
[7] = "Elementar (Wowhead)",
-- c4c0aa4c English: Wowhead's Elemental, an alternative to the recommended Icy Veins Elemental
--     premade, off by default: enable it and disable that one, or raise its priority. At 70 Chain
--     Lightning on cooldown with Lightning Bolts in between (while leveling only with Elemental
--     Mastery or Clearcasting), Flame Shock only while moving, Earth Shock to finish a target that
--     would die before a cast lands. Same totem, shield and cooldown reminders as the Icy Veins
--     variant.
[8] = "Elementar nach Wowhead, eine Alternative zur empfohlenen integrierten Elementarrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Auf Stufe 70 Kettenblitzschlag bei Abklingzeit-Ende mit Blitzschlägen dazwischen (beim Leveln nur mit Elementarbeherrschung oder Freizaubern), Flammenschock nur in Bewegung, Erdschock, um ein Ziel zu erledigen, das stürbe, bevor ein Zauber ankommt. Dieselben Erinnerungen an Totems, Schild und Abklingzeiten wie die Icy-Veins-Variante.",
-- bb13bf18 English: Elemental (NextActionTBC)
-- Context: Name of a Built In rotation for TBC Shaman, Elemental spec, based on the NextActionTBC
--     addon's logic; the source is in parentheses.
[9] = "Elementar (NextActionTBC)",
-- 2ec2f692 English: NextActionTBC's Elemental, an alternative to the recommended Icy Veins
--     Elemental premade, off by default: enable it and disable that one, or raise its priority.
--     Keeps Flame Shock on the target, Chain Lightning only against two or more enemies while above
--     30% mana, Lightning Bolt otherwise. Reminds you of Lightning Shield, a weapon imbue,
--     Elemental Mastery and Bloodlust/Heroism; totems stay manual.
[10] = "Elementar nach NextActionTBC, eine Alternative zur empfohlenen integrierten Elementarrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Hält Flammenschock auf dem Ziel, Kettenblitzschlag nur gegen zwei oder mehr Gegner bei über 30 % Mana, sonst Blitzschlag. Erinnert an Blitzschlagschild, eine Waffenverzauberung, Elementarbeherrschung und Kampfrausch/Heldentum; Totems bleiben manuell.",
-- e6f434e0 English: Healing for the Restoration talent tree, on your friendly target (or yourself
--     with no target): Nature's Swiftness and Healing Wave or Lesser Healing Wave in emergencies,
--     Cure Poison and Cure Disease, Earth Shield on your focus, Chain Heal when three nearby allies
--     are hurt, Healing Wave otherwise. With a hostile target it switches to Flame Shock and
--     Lightning Bolt for soloing. Reminders: Water Shield, Earth Shield on your focus (set the tank
--     as focus), Mana Tide, Mana Spring and Strength of Earth in a group, Bloodlust/Heroism.
--     Choosing whom to heal and which rank stays with you.
[11] = "Heilung für den Talentbaum Wiederherstellung, auf Ihr freundliches Ziel (oder Sie selbst ohne Ziel): Schnelligkeit der Natur und Welle der Heilung oder Geringe Welle der Heilung im Notfall, Vergiftung heilen und Krankheit heilen, Erdschild auf Ihrem Fokus, Kettenheilung, wenn drei nahe Verbündete verletzt sind, sonst Welle der Heilung. Mit einem feindlichen Ziel wechselt sie für das Solospiel zu Flammenschock und Blitzschlag. Erinnerungen: Wasserschild, Erdschild auf Ihrem Fokus (legen Sie den Tank als Fokus fest), Totem der Manaflut, Totem der Manaquelle und Totem der Erdstärke in einer Gruppe, Kampfrausch/Heldentum. Wen Sie heilen und mit welchem Rang, bleibt Ihnen überlassen.",
-- d54e5a0a English: Healing once Restoration is your main talent tree with 16 points (Mana Tide
--     Totem's tier), after Icy Veins. With a friendly target: an instant Healing Wave once you use
--     Nature's Swiftness, Cure Poison and Cure Disease, Riptide on a target without it, Chain Heal
--     in a group, Healing Wave. You pick who to heal by targeting them; health and mana are hidden
--     from addons on Forever, so when to use Nature's Swiftness and Lesser Healing Wave is your
--     call. With a hostile target and nothing to heal: Fire Nova and Chain Lightning on packs,
--     Stormstrike and Earth Shock if you know Stormstrike, Flame Shock on elites and bosses,
--     Lightning Bolt, then melee. Reminders: Water Shield, the Earth Shock interrupt, Mana Tide and
--     group buff totems. Left to you: downranking, other totems, Purge and Ghost Wolf.
[12] = "Heilung, sobald Wiederherstellung Ihr Haupttalentbaum mit 16 Punkten ist (die Stufe von Totem der Manaflut), nach Icy Veins. Mit einem freundlichen Ziel: eine sofortige Welle der Heilung, sobald Sie Schnelligkeit der Natur nutzen, Vergiftung heilen und Krankheit heilen, Springflut auf ein Ziel ohne sie, Kettenheilung in einer Gruppe, Welle der Heilung. Wen Sie heilen, wählen Sie durch Anvisieren; Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie Schnelligkeit der Natur und Geringe Welle der Heilung einsetzen. Mit einem feindlichen Ziel und nichts zu heilen: Feuernova und Kettenblitzschlag gegen Gruppen, Sturmschlag und Erdschock, wenn Sie Sturmschlag beherrschen, Flammenschock auf Elitegegner und Bosse, Blitzschlag, dann Nahkampf. Erinnerungen: Wasserschild, Erdschock als Unterbrechung, Totem der Manaflut und Gruppen-Stärkungstotems. Ihnen überlassen: Herabstufen von Rängen, andere Totems, Reinigen und Geisterwolf.",
-- 2fcd0801 English: Ranged Elemental once Elemental is your main talent tree with 21 points (Lava
--     Burst's tier), after Icy Veins (before that the Enhancement premade plays the melee hybrid
--     every guide recommends). Pulls with Lightning Bolt (Chain Lightning on a pack), casts only
--     instants while moving, uses Fire Nova and Chain Lightning on three or more enemies, keeps
--     Flame Shock up, Lava Burst on cooldown, Stormstrike and Earth Shock if you know Stormstrike,
--     Fire Nova on Clearcasting in groups, then Lightning Bolt. Reminders: shield, weapon imbue,
--     Searing or Magma Totem, group totems, Elemental Mastery, interrupt. Health and mana are
--     hidden from addons on Forever, so healing yourself and pausing to refill mana are your call.
--     Left to you: Earthbind kiting, Frost Shock, Purge and other totems.
[13] = "Elementar im Fernkampf, sobald Elementar Ihr Haupttalentbaum mit 21 Punkten ist (die Stufe von Lavaeruption), nach Icy Veins (davor spielt die integrierte Verstärkungsrotation den Nahkampf-Hybrid, den jeder Leitfaden empfiehlt). Zieht mit Blitzschlag (Kettenblitzschlag gegen eine Gruppe), wirkt in Bewegung nur Spontanzauber, nutzt Feuernova und Kettenblitzschlag gegen drei oder mehr Gegner, hält Flammenschock aufrecht, Lavaeruption bei Abklingzeit-Ende, Sturmschlag und Erdschock, wenn Sie Sturmschlag beherrschen, Feuernova bei Freizaubern in Gruppen, dann Blitzschlag. Erinnerungen: Schild, Waffenverzauberung, Totem der Verbrennung oder Totem der glühenden Magma, Gruppentotems, Elementarbeherrschung, Unterbrechung. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie sich heilen und für Mana pausieren. Ihnen überlassen: Kiten mit Totem der Erdbindung, Frostschock, Reinigen und andere Totems.",
-- 339ec7e4 English: Melee Enhancement from level 1 to 60, and the default for any Shaman before
--     Lava Burst or Mana Tide Totem. Pulls with Lightning Bolt from range, then Stormstrike on
--     cooldown, an instant Lightning Bolt at five Maelstrom Weapon stacks, Fire Nova (with a Fire
--     totem down) and Flame Shock on three or more enemies, Earth Shock into the Stormstrike
--     debuff, Flame Shock in groups, and Earth Shock on cooldown; Lightning Bolt fills the gap
--     while the target is out of reach. Health and mana are hidden from addons on Forever, so
--     healing yourself and pausing to refill mana are your call (the Wowhead premade saves mana
--     instead). Reminders: weapon imbue (Windfury, else Flametongue, else Rockbiter), Water or
--     Lightning Shield, the Earth Shock interrupt, Searing or Magma Totem, group totems, Rage of
--     the Farseer, Stoneclaw Totem. Left to you: totem presets, Frost Shock, Purge and other
--     totems.
[14] = "Verstärkung im Nahkampf von Stufe 1 bis 60 und der Standard für jeden Schamanen vor Lavaeruption oder Totem der Manaflut. Zieht mit Blitzschlag aus der Distanz, dann Sturmschlag bei Abklingzeit-Ende, ein sofortiger Blitzschlag bei fünf Stapeln Waffe des Mahlstroms, Feuernova (mit einem gesetzten Feuertotem) und Flammenschock gegen drei oder mehr Gegner, Erdschock in den Schwächungszauber von Sturmschlag, Flammenschock in Gruppen und Erdschock bei Abklingzeit-Ende; Blitzschlag füllt die Lücke, solange das Ziel außer Reichweite ist. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie sich heilen und für Mana pausieren (die integrierte Rotation nach Wowhead spart stattdessen Mana). Erinnerungen: Waffenverzauberung (Waffe des Windzorns, sonst Waffe der Flammenzunge, sonst Waffe des Felsbeißers), Wasser- oder Blitzschlagschild, Erdschock als Unterbrechung, Totem der Verbrennung oder Totem der glühenden Magma, Gruppentotems, Zorn des Scharfsehers, Totem der Steinklaue. Ihnen überlassen: Totem-Voreinstellungen, Frostschock, Reinigen und andere Totems.",
-- eb2363b2 English: Enhancement, mana-efficient (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Shaman,
--     WoW Forever (variant key: Enhancement / Wowhead). Names in parentheses (guide or tool such as
--     Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are
--     proper names and stay unchanged.
[15] = "Verstärkung, manasparend (Wowhead)",
-- abc72f43 English: Wowhead's and Mobalytics' mana-saving Enhancement: auto-attack does the work,
--     Stormstrike only while Improved Stormstrike's mana regeneration is down, no Earth Shock in
--     the rotation (shocks pull and interrupt), and in groups or on packs Searing Totem with Fire
--     Nova on cooldown. Same imbue, shield and interrupt reminders as the Icy Veins premade. Choose
--     it instead of that premade if mana runs out. An alternative to the recommended Enhancement
--     premade, off by default: enable it and disable that one, or raise its priority.
[16] = "Manasparende Verstärkung nach Wowhead und Mobalytics: Der automatische Angriff erledigt die Arbeit, Sturmschlag nur, solange die Manaregeneration von Verbesserter Sturmschlag nicht aktiv ist, kein Erdschock in der Rotation (Schocks zum Pullen und Unterbrechen), und in Gruppen oder gegen mehrere Gegner Totem der Verbrennung mit Feuernova bei Abklingzeit-Ende. Dieselben Erinnerungen an Waffenverzauberung, Schild und Unterbrechung wie die integrierte Rotation nach Icy Veins. Wählen Sie diese statt jener, wenn Ihnen das Mana ausgeht. Eine Alternative zur empfohlenen integrierten Verstärkungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 14b1a04b English: Recommended for Elemental in Midnight. In combat the game now hides Flame
--     Shock, your buffs, Maelstrom, cooldown times and health from addons, so this shows Blizzard's
--     own Assisted Combat suggestion (the one-button rotation), and stops while you cast or have no
--     enemy targeted. Reminders for what it leaves out: Ascendance, Fire or Storm Elemental and
--     Nature's Swiftness in combat, Spiritwalker's Grace while moving, Lightning Shield and Skyfury
--     between pulls (Blizzard's suggestion keeps your weapon and shield imbues), Wind Shear on an
--     interruptible cast (it lights only where the game lets the cast be read), Astral Shift
--     whenever it is ready in combat (health is hidden on Retail, so when to use it is your call).
[17] = "Empfohlen für Elementar in Midnight. Im Kampf verbirgt das Spiel nun Flammenschock, Ihre Stärkungszauber, Mahlstrom, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Aszendenz, Feuer- oder Sturmelementar und Schnelligkeit der Natur im Kampf, Gunst des Geistwandlers in Bewegung, Blitzschlagschild und Himmelszorn zwischen den Kämpfen (Blizzards Vorschlag hält Ihre Waffen- und Schildverzauberungen aufrecht), Windstoß bei einem unterbrechbaren Zauber (er leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt), Astralverschiebung, wann immer sie im Kampf bereit ist (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen).",
-- 8fc57d38 English: Reference only, off by default: the Icy Veins and SimulationCraft order reads
--     Flame Shock, Master of the Elements and Stormkeeper, which Midnight hides in combat;
--     Maelstrom is hidden on Retail, so the spenders go at their cost instead of near full
--     Maelstrom. Stormkeeper and Lava Burst before the pull. On three or more engaged enemies:
--     Stormkeeper, Ancestral Swiftness, Flame Shock, Chain Lightning with Stormkeeper, Elemental
--     Blast, Earthquake, Lava Burst on Lava Surge, Tempest, Chain Lightning. Otherwise Stormkeeper,
--     Ancestral Swiftness, Flame Shock and Voltaic Blaze in their last 30% outside Master of the
--     Elements, Lava Burst to start it, Tempest and Stormkeeper's Lightning Bolt inside it,
--     Elemental Blast or Earth Shock inside it, Voltaic Blaze, Tempest, Flame Shock or Frost Shock
--     while moving, Elemental Blast or Earth Shock whenever you can afford it, Lightning Bolt.
--     Reminders: Ascendance once Stormkeeper is used, elementals, Spiritwalker's Grace, and the
--     shared ones.
[18] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest Flammenschock, Meister der Elemente und Sturmhüter, die Midnight im Kampf verbirgt; Mahlstrom ist unter Retail verborgen, daher werden die Verbraucher zu ihren Kosten eingesetzt statt bei fast vollem Mahlstrom. Sturmhüter und Lavaeruption vor dem Pull. Gegen drei oder mehr Gegner im Kampf: Sturmhüter, Schnelligkeit der Ahnen, Flammenschock, Kettenblitzschlag mit Sturmhüter, Elementarschlag, Erdbeben, Lavaeruption bei Lavasog, Sturmgewitter, Kettenblitzschlag. Sonst Sturmhüter, Schnelligkeit der Ahnen, Flammenschock und Voltaiklohe in ihren letzten 30 % außerhalb von Meister der Elemente, Lavaeruption, um es auszulösen, Sturmgewitter und Blitzschlag mit Sturmhüter währenddessen, Elementarschlag oder Erdschock währenddessen, Voltaiklohe, Sturmgewitter, Flammenschock oder Frostschock in Bewegung, Elementarschlag oder Erdschock, wann immer Sie es sich leisten können, Blitzschlag. Erinnerungen: Aszendenz, sobald Sturmhüter verbraucht ist, Elementare, Gunst des Geistwandlers und die gemeinsamen.",
-- 2b518620 English: Recommended for Enhancement in Midnight. Shows Blizzard's Assisted Combat
--     suggestion (it spends Maelstrom Weapon, keeps Flame Shock and handles Surging Totem and
--     Sundering), and stops while you cast or have no enemy targeted. Reminders for what it leaves
--     out: Ascendance, Doom Winds and Feral Spirit in combat, Lightning Shield and Skyfury between
--     pulls (Blizzard's suggestion keeps Windfury Weapon), Wind Shear, Astral Shift.
[19] = "Empfohlen für Verstärkung in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (er verbraucht Waffe des Mahlstroms, hält Flammenschock aufrecht und übernimmt Wogendes Totem und Zerschlagung) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Aszendenz, Schicksalswinde und Wildgeist im Kampf, Blitzschlagschild und Himmelszorn zwischen den Kämpfen (Blizzards Vorschlag hält Waffe des Windzorns aufrecht), Windstoß, Astralverschiebung.",
-- 5c90fed4 English: Stormbringer reference (SimulationCraft)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Shaman,
--     Retail (current expansion) (variant key: Enhancement / Stormbringer). Names in parentheses
--     (guide or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics,
--     Warcraft Tavern) are proper names and stay unchanged.
[20] = "Sturmbringer-Referenz (SimulationCraft)",
-- 4890c5e6 English: Reference only, off by default: SimulationCraft's Stormbringer list (Icy Veins
--     and Wowhead agree) reads Flame Shock, Crash Lightning, Lashing Flames and cooldown timers,
--     which Midnight hides in combat. On three or more engaged enemies: Crash Lightning for its
--     buff, Tempest at 10 Maelstrom Weapon, Chain Lightning at 9, Crash Lightning, Lava Lash,
--     Sundering. Then Primordial Storm at 9, Voltaic Blaze or Flame Shock when Flame Shock is
--     missing, Sundering, Crash Lightning for its buff, Lava Lash for Lashing Flames, Windstrike,
--     Tempest or Lightning Bolt at 10 (8 with Voltaic Blaze or Crash Lightning about ready),
--     Stormstrike at two charges, Lava Lash, Stormstrike, Voltaic Blaze, Crash Lightning, Lightning
--     Bolt at 5, Flame Shock. Reminders: Doom Winds, Ascendance outside Doom Winds, Feral Spirit,
--     and the shared ones.
[21] = "Nur als Referenz, standardmäßig deaktiviert: die Sturmbringer-Liste von SimulationCraft (Icy Veins und Wowhead stimmen überein) liest Flammenschock, Tobende Blitze, Peitschende Flammen und Abklingzeit-Timer, die Midnight im Kampf verbirgt. Gegen drei oder mehr Gegner im Kampf: Tobende Blitze für den Stärkungszauber, Sturmgewitter bei 10 Stapeln Waffe des Mahlstroms, Kettenblitzschlag bei 9, Tobende Blitze, Lavapeitsche, Zerschlagung. Dann Urzeitlicher Sturm bei 9, Voltaiklohe oder Flammenschock, wenn Flammenschock fehlt, Zerschlagung, Tobende Blitze für den Stärkungszauber, Lavapeitsche für Peitschende Flammen, Windschlag, Sturmgewitter oder Blitzschlag bei 10 (8, wenn Voltaiklohe oder Tobende Blitze fast bereit sind), Sturmschlag bei zwei Aufladungen, Lavapeitsche, Sturmschlag, Voltaiklohe, Tobende Blitze, Blitzschlag bei 5, Flammenschock. Erinnerungen: Schicksalswinde, Aszendenz außerhalb von Schicksalswinden, Wildgeist und die gemeinsamen.",
-- 33731fb7 English: Totemic reference (SimulationCraft)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Shaman,
--     Retail (current expansion) (variant key: Enhancement / Totemic). Names in parentheses (guide
--     or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[22] = "Totemiker-Referenz (SimulationCraft)",
-- 4485ad39 English: Reference only, off by default: SimulationCraft's Totemic list reads Flame
--     Shock, Hot Hand, Whirling Fire, Crash Lightning and Doom Winds, which Midnight hides in
--     combat. On three or more engaged enemies: Crash Lightning, Chain Lightning at 5 Maelstrom
--     Weapon. Then Voltaic Blaze or Flame Shock when Flame Shock is missing, Surging Totem,
--     Sundering, Lava Lash with Hot Hand or Whirling Fire, Crash Lightning for its buff, Primordial
--     Storm at 10, Windstrike, Crash Lightning and Stormstrike in Doom Winds, Lightning Bolt at 5,
--     Crash Lightning, Lava Lash, Stormstrike, Voltaic Blaze, Flame Shock. Same reminders as the
--     Stormbringer reference.
[23] = "Nur als Referenz, standardmäßig deaktiviert: die Totemiker-Liste von SimulationCraft liest Flammenschock, Heiße Hand, Wirbelndes Feuer, Tobende Blitze und Schicksalswinde, die Midnight im Kampf verbirgt. Gegen drei oder mehr Gegner im Kampf: Tobende Blitze, Kettenblitzschlag bei 5 Stapeln Waffe des Mahlstroms. Dann Voltaiklohe oder Flammenschock, wenn Flammenschock fehlt, Wogendes Totem, Zerschlagung, Lavapeitsche mit Heißer Hand oder Wirbelndem Feuer, Tobende Blitze für den Stärkungszauber, Urzeitlicher Sturm bei 10, Windschlag, Tobende Blitze und Sturmschlag während Schicksalswinden, Blitzschlag bei 5, Tobende Blitze, Lavapeitsche, Sturmschlag, Voltaiklohe, Flammenschock. Dieselben Erinnerungen wie die Sturmbringer-Referenz.",
-- 6bac9c2a English: Restoration in Midnight, for reference: Blizzard's Assisted Combat does not
--     cover healers, the game hides everyone's health in combat and Rotation Master picks a spell,
--     not a target, so this orders your healing tools by readiness on whatever you target and
--     leaves deciding who to heal to you. On a friendly target: Healing Stream Totem, Unleash Life,
--     Healing Rain in a group, Surging Totem, Riptide, Chain Heal in a group, Healing Wave. On an
--     enemy: Flame Shock when missing, Lava Burst, Lightning Bolt. Reminders: Water Shield, Earth
--     Shield on a friendly target and Skyfury between pulls; Nature's Swiftness in combat; Healing
--     Tide Totem and Spirit Link Totem in grouped combat; Wind Shear; Astral Shift.
[24] = "Wiederherstellung in Midnight, als Referenz: Blizzards Kampfassistent deckt keine Heiler ab, das Spiel verbirgt im Kampf die Gesundheit aller, und Rotation Master wählt einen Zauber, kein Ziel, daher ordnet diese Rotation Ihre Heilwerkzeuge auf jedem Ziel, das Sie anvisieren, nach Bereitschaft und überlässt Ihnen die Entscheidung, wen Sie heilen. Bei einem freundlichen Ziel: Totem des heilenden Flusses, Leben entfesseln, Heilender Regen in einer Gruppe, Wogendes Totem, Springflut, Kettenheilung in einer Gruppe, Welle der Heilung. Bei einem Gegner: Flammenschock, wenn er fehlt, Lavaeruption, Blitzschlag. Erinnerungen: Wasserschild, Erdschild auf einem freundlichen Ziel und Himmelszorn zwischen den Kämpfen; Schnelligkeit der Natur im Kampf; Totem der Heilungsflut und Totem der Geistverbindung im Gruppenkampf; Windstoß; Astralverschiebung.",
-- 75442137 English: Recommended before you choose a specialization (while the game reports the
--     Shaman's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Shaman premade shares, each once
--     you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[25] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Schamanen meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Schamane-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung.",
-- e9357a95 English: Levels 1–60, also on Hardcore and Self-Found realms, and every Shaman without a
--     talent majority; built from Icy Veins, Wowhead and simulator. Lightning Bolt pulls from
--     range; Earth Shock interrupts. In raids only Stormstrike and Frost Shock (debuff slots). On
--     three or more enemies fighting you, Fire Nova and Magma totems. Then Stormstrike, Earth Shock
--     into the Stormstrike debuff or to finish, Flame Shock when it will run its course, Earth
--     Shock while you have half your mana, and Lightning Bolt while out of reach. Reminders:
--     Rockbiter solo and Windfury Weapon in dungeons, Lightning Shield, Strength of Earth, Searing,
--     Windfury or Grace of Air, Mana Spring or Healing Stream, healing after a pull and in
--     emergencies. Stoneclaw, Earthbind, totem twisting and racials are listed off; dispels, purges
--     and cleansing totems stay with you.
[26] = "Stufen 1–60, auch auf Hardcore- und Self-Found-Realms, und jeder Schamane ohne Talentschwerpunkt; zusammengestellt aus Icy Veins, Wowhead und Simulation. Blitzschlag zieht aus der Distanz; Erdschock unterbricht. In Schlachtzügen nur Sturmschlag und Frostschock (Plätze für Schwächungszauber). Wenn drei oder mehr Gegner gegen Sie kämpfen, Totem der Feuernova und Totem der glühenden Magma. Dann Sturmschlag, Erdschock in den Schwächungszauber von Sturmschlag oder zum Erledigen, Flammenschock, wenn er voll durchlaufen kann, Erdschock, solange Sie die Hälfte Ihres Manas haben, und Blitzschlag, solange das Ziel außer Reichweite ist. Erinnerungen: Waffe des Felsbeißers solo und Waffe des Windzorns in Dungeons, Blitzschlagschild, Totem der Erdstärke, Totem der Verbrennung, Totem des Windzorns oder der luftgleichen Anmut, Totem der Manaquelle oder des heilenden Flusses, Heilung nach einem Pull und im Notfall. Totem der Steinklaue, Totem der Erdbindung, Totem-Twisting und Volksfähigkeiten sind als deaktivierte Schritte aufgeführt; Bannungen, Reinigen und Reinigungstotems bleiben Ihnen überlassen.",
-- 327189d1 English: Enhancement, Flame Shock first (Warcraft Tavern)
[27] = "Verstärkung, Flammenschock zuerst (Warcraft Tavern)",
-- bc01445d English: Warcraft Tavern's Enhancement, an alternative to the recommended Enhancement
--     premade, off by default: enable it and disable that one, or raise its priority. Windfury
--     Weapon as soon as you learn it, Stormstrike, Flame Shock before any direct shock, then Earth
--     Shock while your threat is low, or Frost Shock in a group once it is high; Magma and Chain
--     Lightning on packs. Same totems and reminders as the recommended premade.
[28] = "Verstärkung nach Warcraft Tavern, eine Alternative zur empfohlenen integrierten Verstärkungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Waffe des Windzorns, sobald Sie sie erlernen, Sturmschlag, Flammenschock vor jedem direkten Schock, dann Erdschock, solange Ihre Bedrohung niedrig ist, oder in einer Gruppe Frostschock, sobald sie hoch ist; Totem der glühenden Magma und Kettenblitzschlag gegen Gruppen. Dieselben Totems und Erinnerungen wie die empfohlene integrierte Rotation.",
-- 5ee9955c English: Elemental from level 10 (most points in Elemental); built from Icy Veins and
--     Wowhead. Earth Shock interrupts and finishes a target about to die. While moving: Flame
--     Shock, else Frost Shock. Solo with the target in melee: Earth Shock above 30% health, then
--     melee. On three or more enemies: Fire Nova and Magma totems when you are in melee, and Chain
--     Lightning. Chain Lightning under Elemental Mastery or Clearcasting, otherwise Lightning Bolt.
--     Reminders: Lightning Shield, Rockbiter outside raids, Searing or Magma, Mana Spring or
--     Healing Stream, Elemental Mastery with Chain Lightning ready, Nature's Swiftness and Healing
--     Wave below 30%, healing after a pull. Dispels, purges and downranking stay with you.
[29] = "Elementar ab Stufe 10 (die meisten Punkte in Elementar); zusammengestellt aus Icy Veins und Wowhead. Erdschock unterbricht und erledigt ein Ziel kurz vor dem Tod. In Bewegung: Flammenschock, sonst Frostschock. Solo mit dem Ziel im Nahkampf: Erdschock über 30 % Gesundheit, dann Nahkampf. Gegen drei oder mehr Gegner: Totem der Feuernova und Totem der glühenden Magma, wenn Sie im Nahkampf sind, und Kettenblitzschlag. Kettenblitzschlag während Elementarbeherrschung oder Freizaubern, sonst Blitzschlag. Erinnerungen: Blitzschlagschild, Waffe des Felsbeißers außerhalb von Schlachtzügen, Totem der Verbrennung oder der glühenden Magma, Totem der Manaquelle oder des heilenden Flusses, Elementarbeherrschung bei bereitem Kettenblitzschlag, Schnelligkeit der Natur und Welle der Heilung unter 30 %, Heilung nach einem Pull. Bannungen, Reinigen und Herabstufen von Rängen bleiben Ihnen überlassen.",
-- f652ee1c English: Elemental, Chain Lightning on cooldown (simulator)
[30] = "Elementar, Kettenblitzschlag bei Abklingzeit-Ende (Simulation)",
-- a3ba0441 English: The simulator Elemental list, an alternative to the recommended Elemental
--     premade, off by default: enable it and disable that one, or raise its priority. Chain
--     Lightning on cooldown even on one target, Earth Shock while Elemental Mastery is up,
--     otherwise Lightning Bolt. Faster but much hungrier for mana than the recommended premade;
--     same interrupt, totems and reminders.
[31] = "Die Elementar-Liste von Simulation, eine Alternative zur empfohlenen integrierten Elementarrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Kettenblitzschlag bei Abklingzeit-Ende, selbst gegen ein einzelnes Ziel, Erdschock, solange Elementarbeherrschung aktiv ist, sonst Blitzschlag. Schneller, aber viel manahungriger als die empfohlene integrierte Rotation; dieselbe Unterbrechung, dieselben Totems und Erinnerungen.",
-- 5119f4dc English: Restoration from level 10 (most points in Restoration); built from Icy Veins
--     and Wowhead. On your friendly target: Healing Wave under Nature's Swiftness, Nature's
--     Swiftness below 30%, Lesser Healing Wave below 40%, Cure Poison or Cure Disease, Chain Heal
--     when three group members near you are below 85%, otherwise Healing Wave below 90%. On an
--     enemy it fights: Earth Shock interrupt, Chain Lightning on packs, Flame Shock, Lightning Bolt
--     from range, melee. Reminders: Lightning Shield and Rockbiter solo, Mana Tide in a group, Mana
--     Spring, Strength of Earth, Searing. Choosing whom to heal, downranking and Tremor or
--     cleansing totems stay with you; keeping Healing Way on the tank is listed off.
[32] = "Wiederherstellung ab Stufe 10 (die meisten Punkte in Wiederherstellung); zusammengestellt aus Icy Veins und Wowhead. Auf Ihr freundliches Ziel: Welle der Heilung während Schnelligkeit der Natur, Schnelligkeit der Natur unter 30 %, Geringe Welle der Heilung unter 40 %, Vergiftung heilen oder Krankheit heilen, Kettenheilung, wenn drei Gruppenmitglieder in Ihrer Nähe unter 85 % sind, sonst Welle der Heilung unter 90 %. Gegen einen Gegner, den sie bekämpft: Erdschock als Unterbrechung, Kettenblitzschlag gegen Gruppen, Flammenschock, Blitzschlag aus der Distanz, Nahkampf. Erinnerungen: Blitzschlagschild und Waffe des Felsbeißers solo, Totem der Manaflut in einer Gruppe, Totem der Manaquelle, Totem der Erdstärke, Totem der Verbrennung. Wen Sie heilen, Herabstufen von Rängen und Totem des Erdstoßes oder Reinigungstotems bleiben Ihnen überlassen; Pfad der Heilung auf dem Tank zu halten ist als deaktivierter Schritt aufgeführt.",
-- 4e388ff1 English: Restoration, Chain Heal first (Warcraft Tavern)
[33] = "Wiederherstellung, Kettenheilung zuerst (Warcraft Tavern)",
-- 7528f628 English: Warcraft Tavern's Restoration, an alternative to the recommended Restoration
--     premade, off by default: enable it and disable that one, or raise its priority. Chain Heal is
--     the heal for anyone below 90%, with Lesser Healing Wave for someone about to die; Healing
--     Wave is only for an assigned tank healer with Healing Way (listed off). Same cures, damage on
--     enemies and totem reminders as the recommended premade.
[34] = "Wiederherstellung nach Warcraft Tavern, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Kettenheilung ist die Heilung für jeden unter 90 %, mit Geringer Welle der Heilung für jemanden kurz vor dem Tod; Welle der Heilung ist nur für einen zugewiesenen Tankheiler mit Pfad der Heilung gedacht (als deaktivierter Schritt aufgeführt). Dieselben Reinigungen, derselbe Schaden gegen Gegner und dieselben Totem-Erinnerungen wie die empfohlene integrierte Rotation.",
-- 37e5b161 English: Enhancement (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Shaman,
--     Season of Discovery (variant key: Enhancement). Names in parentheses (guide or tool such as
--     Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are
--     proper names and stay unchanged.
[35] = "Verstärkung (SoD)",
-- 64d2c56f English: Season of Discovery, levels 1–60 with runes as you engrave them, dual wield or
--     two-hander, and every SoD Shaman no other premade fits; built from simulator Phase 6, Icy
--     Veins and Wowhead. Flame Shock pulls; Earth Shock interrupts. On three or more enemies:
--     Magma, Fire Nova from a fire totem, Chain Lightning at four Maelstrom stacks, Flame Shock.
--     Then Lava Burst at five Maelstrom stacks, Stormstrike, Lava Lash, Lightning Bolt at five
--     stacks, Flame Shock when it will run, Earth Shock, Molten Blast, Lightning Bolt from range.
--     Reminders: Windfury Weapon (Rockbiter before), Flametongue on an off-hand weapon with Lava
--     Lash (else Windfury; never on a shield; an Icy Veins Windfury-both line is listed off), Water
--     or Lightning Shield, Spirit of the Alpha, Feral Spirit, Shamanistic Rage below 65% mana,
--     totems, Ancestral Guidance. Totemic Projection, dispels and purges stay with you.
[36] = "Saison der Entdeckungen, Stufen 1–60 mit Runen, sobald Sie sie gravieren, Beidhändigkeit oder Zweihandwaffe, und jeder Schamane der Saison der Entdeckungen, zu dem keine andere integrierte Rotation passt; zusammengestellt aus Simulation Phase 6, Icy Veins und Wowhead. Flammenschock zieht; Erdschock unterbricht. Gegen drei oder mehr Gegner: Totem der glühenden Magma, Feuernova von einem Feuertotem, Kettenblitzschlag bei vier Stapeln von Waffe des Mahlstroms, Flammenschock. Dann Lavaeruption bei fünf Stapeln von Waffe des Mahlstroms, Sturmschlag, Lavapeitsche, Blitzschlag bei fünf Stapeln, Flammenschock, wenn er durchlaufen kann, Erdschock, Schmelzschlag, Blitzschlag aus der Distanz. Erinnerungen: Waffe des Windzorns (davor Waffe des Felsbeißers), Waffe der Flammenzunge auf einer Schildhandwaffe mit Lavapeitsche (sonst Windzorn; nie auf einem Schild; eine Zeile von Icy Veins mit Windzorn auf beiden Waffen ist als deaktivierter Schritt aufgeführt), Wasser- oder Blitzschlagschild, Geist des Alphas, Wildgeist, Schamanistische Wut unter 65 % Mana, Totems, Führung der Ahnen. Totemische Projektion, Bannungen und Reinigen bleiben Ihnen überlassen.",
-- 0fb65642 English: Elemental (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Shaman,
--     Season of Discovery (variant key: Elemental). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[37] = "Elementar (SoD)",
-- 90cd327e English: Season of Discovery Elemental from level 10 (most points in Elemental); built
--     from simulator Phase 6, Wowhead and Icy Veins. Earth Shock interrupts. While moving: Flame
--     Shock, Earth Shock at eight Lightning Shield charges, Lava Burst or Chain Lightning on a
--     Power Surge proc. On three or more enemies: Flame Shock, Chain Lightning, Fire Nova, Lava
--     Burst, Earth Shock at eight charges, Magma. Then Lava Burst on Power Surge, Flame Shock kept
--     up, Lava Burst while your Flame Shock lasts, Earth Shock at eight charges, Chain Lightning on
--     two enemies, Lightning Bolt. Reminders: Flametongue for Burn, Lightning Shield, Earth Shield
--     on yourself, Spirit of the Alpha, Feral Spirit, Shamanistic Rage, Elemental Mastery, totems.
--     Trinkets, Totemic Projection, dispels and purges stay with you.
[38] = "Elementar in der Saison der Entdeckungen ab Stufe 10 (die meisten Punkte in Elementar); zusammengestellt aus Simulation Phase 6, Wowhead und Icy Veins. Erdschock unterbricht. In Bewegung: Flammenschock, Erdschock bei acht Aufladungen von Blitzschlagschild, Lavaeruption oder Kettenblitzschlag bei einem Proc von Kraftwoge. Gegen drei oder mehr Gegner: Flammenschock, Kettenblitzschlag, Feuernova, Lavaeruption, Erdschock bei acht Aufladungen, Totem der glühenden Magma. Dann Lavaeruption bei Kraftwoge, Flammenschock aufrechterhalten, Lavaeruption, solange Ihr Flammenschock anhält, Erdschock bei acht Aufladungen, Kettenblitzschlag gegen zwei Gegner, Blitzschlag. Erinnerungen: Waffe der Flammenzunge für Brennen, Blitzschlagschild, Erdschild auf Ihnen selbst, Geist des Alphas, Wildgeist, Schamanistische Wut, Elementarbeherrschung, Totems. Schmuckstücke, Totemische Projektion, Bannungen und Reinigen bleiben Ihnen überlassen.",
-- ff16512c English: Season of Discovery Restoration from level 10 (most points in Restoration);
--     built from Icy Veins and Wowhead. On your friendly target: Riptide then Lesser Healing Wave
--     below 40%, Cure Poison or Cure Disease, Healing Rain when three group members near you are
--     below 85%, Chain Heal when two are (at once on a Power Surge proc), Riptide below 95% for
--     Tidal Waves, Healing Wave below 90%. On an enemy it fights. Reminders: Water Shield
--     (Lightning Shield before), Earth Shield on your friendly target or yourself, Shamanistic
--     Rage, Mana Tide, Mana Spring and Strength of Earth. Choosing whom to heal and Tremor or
--     cleansing totems stay with you.
[39] = "Wiederherstellung in der Saison der Entdeckungen ab Stufe 10 (die meisten Punkte in Wiederherstellung); zusammengestellt aus Icy Veins und Wowhead. Auf Ihr freundliches Ziel: Springflut, dann Geringe Welle der Heilung unter 40 %, Vergiftung heilen oder Krankheit heilen, Heilender Regen, wenn drei Gruppenmitglieder in Ihrer Nähe unter 85 % sind, Kettenheilung, wenn es zwei sind (sofort bei einem Proc von Kraftwoge), Springflut unter 95 % für Flutwellen, Welle der Heilung unter 90 %. Gegen einen Gegner kämpft sie. Erinnerungen: Wasserschild (davor Blitzschlagschild), Erdschild auf Ihrem freundlichen Ziel oder Ihnen selbst, Schamanistische Wut, Totem der Manaflut, Totem der Manaquelle und Totem der Erdstärke. Wen Sie heilen und Totem des Erdstoßes oder Reinigungstotems bleiben Ihnen überlassen.",
-- 007cf117 English: Tank (SoD, Way of Earth)
[40] = "Tank, Weg der Erde (SoD)",
-- 3332db10 English: Season of Discovery tank, chosen once Way of Earth is engraved; built from Icy
--     Veins, Wowhead, simulator and Warcraft Tavern. Flame Shock pulls. Earth Shock taunts a target
--     in melee that is not attacking you, and interrupts. On two or more enemies: Molten Blast,
--     Flame Shock, Chain Lightning at five Maelstrom stacks or on Power Surge, Fire Nova at five
--     stacks. Then Flame Shock kept up, Lava Burst on Power Surge or while Flame Shock lasts,
--     Stormstrike, Earth Shock, Lightning Bolt at five stacks, Molten Blast, Frost Shock.
--     Reminders: Rockbiter, Lightning Shield, Spirit of the Alpha on yourself, Feral Spirit,
--     Shamanistic Rage, Searing or Magma, and group totems.
[41] = "Tank in der Saison der Entdeckungen, gewählt, sobald Weg der Erde graviert ist; zusammengestellt aus Icy Veins, Wowhead, Simulation und Warcraft Tavern. Flammenschock zieht. Erdschock spottet ein Ziel im Nahkampf, das Sie nicht angreift, und unterbricht. Gegen zwei oder mehr Gegner: Schmelzschlag, Flammenschock, Kettenblitzschlag bei fünf Stapeln von Waffe des Mahlstroms oder bei Kraftwoge, Feuernova bei fünf Stapeln. Dann Flammenschock aufrechterhalten, Lavaeruption bei Kraftwoge oder solange Flammenschock anhält, Sturmschlag, Erdschock, Blitzschlag bei fünf Stapeln, Schmelzschlag, Frostschock. Erinnerungen: Waffe des Felsbeißers, Blitzschlagschild, Geist des Alphas auf Ihnen selbst, Wildgeist, Schamanistische Wut, Totem der Verbrennung oder der glühenden Magma und Gruppentotems.",
-- 013214a9 English: Recommended for Elemental from level 10, chosen in the Elemental
--     specialization. Wowhead's order: a Lightning Bolt to open (Lava Burst with Unleashed Fury),
--     Unleash Elements with Unleashed Fury, Flame Shock when it is missing or about to run out on a
--     target that will live, Lava Burst into Flame Shock (and on every Lava Surge), Elemental
--     Blast, Earth Shock at six Lightning Shield charges while Flame Shock has 6 seconds left,
--     Chain Lightning on two enemies, Lightning Bolt. Four or more enemies on you: Magma in melee,
--     free Lava Bursts, Lava Beam in Ascendance, Chain Lightning. While moving it shows only
--     instants. Reminders: Lightning Shield, Flametongue, Searing Totem, Fire Elemental on elites
--     and bosses, Elemental Mastery, Ascendance after a Lava Burst, Ancestral Swiftness, Stormlash
--     and Bloodlust in a group, Wind Shear, Thunderstorm for mana, Shamanistic Rage and Astral
--     Shift when low. Earthquake and Earth Elemental are listed but off. Left to you:
--     Spiritwalker's Grace, Flame Shock on extra targets and where to stand.
[42] = "Empfohlen für Elementar ab Stufe 10, gewählt in der Spezialisierung Elementar. Die Reihenfolge von Wowhead: ein Blitzschlag zum Eröffnen (Lavaeruption mit Entfesseltem Furor), Elemente entfesseln mit Entfesseltem Furor, Flammenschock, wenn er auf einem Ziel, das lange genug lebt, fehlt oder bald ausläuft, Lavaeruption auf Flammenschock (und bei jedem Lavasog), Elementarschlag, Erdschock bei sechs Aufladungen von Blitzschlagschild, solange Flammenschock noch 6 Sekunden hat, Kettenblitzschlag gegen zwei Gegner, Blitzschlag. Vier oder mehr Gegner gegen Sie: Totem des glühenden Magmas im Nahkampf, kostenlose Lavaeruptionen, Lavastrahl während Aszendenz, Kettenblitzschlag. In Bewegung zeigt sie nur Spontanzauber. Erinnerungen: Blitzschlagschild, Waffe der Flammenzunge, Totem der Verbrennung, Totem des Feuerelementars gegen Elitegegner und Bosse, Elementarbeherrschung, Aszendenz nach einer Lavaeruption, Schnelligkeit der Ahnen, Totem der Sturmpeitsche und Kampfrausch in einer Gruppe, Windstoß, Gewitter für Mana, Schamanistische Wut und Astralverschiebung bei niedriger Gesundheit. Erdbeben und Totem des Erdelementars sind aufgeführt, aber deaktiviert. Ihnen überlassen: Gunst des Geistwandlers, Flammenschock auf weiteren Zielen und wo Sie stehen.",
-- 30126acf English: Recommended for Enhancement from level 10, chosen in the Enhancement
--     specialization. Wowhead's order: Unleash Elements while running in, then Unleash Elements
--     with Unleashed Fury, Elemental Blast and Lightning Bolt at five Maelstrom Weapon (or woven at
--     three when your next swing is over a second away), Stormblast in Ascendance, Stormstrike
--     (Primal Strike before 26), Lava Lash, Flame Shock under Unleash Flame, Unleash Elements,
--     Earth Shock. Two or more enemies on you: Chain Lightning instead of Lightning Bolt, Lava Lash
--     to spread Flame Shock, Fire Nova from four, Magma from six. Reminders: Lightning Shield,
--     Windfury on the main hand and Flametongue on the off hand, Searing Totem, Fire Elemental,
--     Feral Spirit, Ascendance after Stormstrike, Elemental Mastery, Ancestral Swiftness, Stormlash
--     and Bloodlust in a group, Wind Shear, Shamanistic Rage and Astral Shift when low. Earth
--     Elemental is listed but off.
[43] = "Empfohlen für Verstärkung ab Stufe 10, gewählt in der Spezialisierung Verstärkung. Die Reihenfolge von Wowhead: Elemente entfesseln beim Heranlaufen, dann Elemente entfesseln mit Entfesseltem Furor, Elementarschlag und Blitzschlag bei fünf Stapeln von Waffe des Mahlstroms (oder bei drei eingewoben, wenn Ihr nächster Schlag mehr als eine Sekunde entfernt ist), Gewitterschlag während Aszendenz, Sturmschlag (Urtümlicher Schlag vor Stufe 26), Lavapeitsche, Flammenschock während Flammen entfesseln, Elemente entfesseln, Erdschock. Zwei oder mehr Gegner gegen Sie: Kettenblitzschlag statt Blitzschlag, Lavapeitsche zum Verteilen von Flammenschock, Feuernova ab vier, Totem des glühenden Magmas ab sechs. Erinnerungen: Blitzschlagschild, Waffe des Windzorns auf der Waffenhand und Waffe der Flammenzunge auf der Schildhand, Totem der Verbrennung, Totem des Feuerelementars, Wildgeist, Aszendenz nach Sturmschlag, Elementarbeherrschung, Schnelligkeit der Ahnen, Totem der Sturmpeitsche und Kampfrausch in einer Gruppe, Windstoß, Schamanistische Wut und Astralverschiebung bei niedriger Gesundheit. Totem des Erdelementars ist aufgeführt, aber deaktiviert.",
-- ada73161 English: Weave every stack (simulator)
[44] = "Jeden Stapel einweben (Simulation)",
-- ab469690 English: Off by default; same switch as the recommended Enhancement premade, so enable
--     it and disable that one to use it. The simulator's list for players who time casts between
--     swings: Lightning Bolt, Elemental Blast or Chain Lightning on any number of Maelstrom Weapon
--     stacks whenever the cast finishes before your next main-hand swing, Unleash Elements also
--     whenever Flame Shock is missing, and Earth Shock only below two stacks. Reminders as the
--     recommended premade.
[45] = "Standardmäßig deaktiviert; dieselbe Umschaltung wie die empfohlene integrierte Verstärkungsrotation, aktivieren Sie sie also und deaktivieren Sie die andere, um sie zu verwenden. Die Liste des Simulators für Spieler, die Zauber zwischen Schlägen timen: Blitzschlag, Elementarschlag oder Kettenblitzschlag bei beliebig vielen Stapeln von Waffe des Mahlstroms, wann immer der Zauber vor Ihrem nächsten Schlag der Waffenhand fertig wird, Elemente entfesseln zusätzlich, wann immer Flammenschock fehlt, und Erdschock nur unter zwei Stapeln. Erinnerungen wie bei der empfohlenen integrierten Rotation.",
-- a926ad7a English: Lava Lash first (Icy Veins)
[46] = "Lavapeitsche zuerst (Icy Veins)",
-- 1509ab70 English: Off by default; same switch as the recommended Enhancement premade, so enable
--     it and disable that one to use it. Icy Veins' order: Stormstrike, then Lava Lash before
--     spending Maelstrom Weapon, Lightning Bolt at five stacks or from three when it lands before
--     your next swing, Unleash Elements then Flame Shock, Earth Shock. On four or more enemies it
--     spreads Flame Shock with Lava Lash and uses Fire Nova; Chain Lightning replaces Lightning
--     Bolt on packs. Shamanistic Rage is suggested on cooldown in combat; other reminders as the
--     recommended premade.
[47] = "Standardmäßig deaktiviert; dieselbe Umschaltung wie die empfohlene integrierte Verstärkungsrotation, aktivieren Sie sie also und deaktivieren Sie die andere, um sie zu verwenden. Die Reihenfolge von Icy Veins: Sturmschlag, dann Lavapeitsche, bevor Waffe des Mahlstroms ausgegeben wird, Blitzschlag bei fünf Stapeln oder ab drei, wenn er vor Ihrem nächsten Schlag landet, Elemente entfesseln, dann Flammenschock, Erdschock. Gegen vier oder mehr Gegner verteilt sie Flammenschock mit Lavapeitsche und nutzt Feuernova; gegen Gruppen ersetzt Kettenblitzschlag den Blitzschlag. Schamanistische Wut wird im Kampf bei Abklingzeit-Ende vorgeschlagen; übrige Erinnerungen wie bei der empfohlenen integrierten Rotation.",
-- 786ac591 English: Recommended for Restoration from level 10, chosen in the Restoration
--     specialization. Heals your friendly target (Rotation Master cannot pick who to heal): Greater
--     Healing Wave under Ancestral Swiftness, Healing Surge below 35%, Purify Spirit on Magic or
--     Curses, Unleash Elements then Healing Rain when three allies nearby are hurt, Riptide, Chain
--     Heal for group damage, Greater Healing Wave below 60%, Healing Wave below 90%. With an
--     attackable target it deals damage instead (Flame Shock, Lava Burst, Elemental Blast,
--     Lightning Bolt). Reminders: Water Shield, Earthliving, Earth Shield on your focus, Healing
--     Stream when someone is hurt, Mana Tide, Healing Tide for heavy group damage, Elemental
--     Mastery or Ancestral Guidance, Ancestral Swiftness on a low target, Spiritwalker's Grace
--     while moving, Bloodlust, Wind Shear. Ascendance and Spirit Link Totem are listed but off: use
--     them when your raid assigns them.
[48] = "Empfohlen für Wiederherstellung ab Stufe 10, gewählt in der Spezialisierung Wiederherstellung. Heilt Ihr freundliches Ziel (Rotation Master kann nicht wählen, wen Sie heilen): Große Welle der Heilung während Schnelligkeit der Ahnen, Heilende Woge unter 35 %, Geistreinigung bei Magie oder Flüchen, Elemente entfesseln, dann Heilender Regen, wenn drei Verbündete in der Nähe verletzt sind, Springflut, Kettenheilung bei Gruppenschaden, Große Welle der Heilung unter 60 %, Welle der Heilung unter 90 %. Mit einem angreifbaren Ziel verursacht sie stattdessen Schaden (Flammenschock, Lavaeruption, Elementarschlag, Blitzschlag). Erinnerungen: Wasserschild, Waffe der Lebensgeister, Erdschild auf Ihrem Fokus, Totem des heilenden Flusses, wenn jemand verletzt ist, Totem der Manaflut, Totem der Heilungsflut bei hohem Gruppenschaden, Elementarbeherrschung oder Führung der Ahnen, Schnelligkeit der Ahnen auf ein Ziel mit wenig Gesundheit, Gunst des Geistwandlers in Bewegung, Kampfrausch, Windstoß. Aszendenz und Totem der Geistverbindung sind aufgeführt, aber deaktiviert: Nutzen Sie sie, wenn Ihr Schlachtzug sie zuweist.",
-- 98ae06d3 English: Health ladder (Hekili)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Shaman,
--     Mists of Pandaria Classic (variant key: Restoration / Hekili). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[49] = "Gesundheitsleiter (Hekili)",
-- db083550 English: Off by default; same switch as the recommended Restoration premade, so enable
--     it and disable that one to use it. Hekili's list keeps Earth Shield and Riptide on your
--     target and Healing Stream and Healing Rain going whenever they are down, then heals by the
--     average health of your group within 40 yards: Chain Heal below 80%, Healing Wave on a target
--     below 70%, Greater Healing Wave below 60%, Healing Surge below 40%, with Healing Tide,
--     Ancestral Guidance and Mana Tide on the same ladder. An attackable target gets damage plus
--     Earth Shock.
[50] = "Standardmäßig deaktiviert; dieselbe Umschaltung wie die empfohlene integrierte Wiederherstellungsrotation, aktivieren Sie sie also und deaktivieren Sie die andere, um sie zu verwenden. Die Liste von Hekili hält Erdschild und Springflut auf Ihrem Ziel und Totem des heilenden Flusses und Heilender Regen am Laufen, wann immer sie fehlen, und heilt dann nach der durchschnittlichen Gesundheit Ihrer Gruppe im Umkreis von 40 Metern: Kettenheilung unter 80 %, Welle der Heilung auf ein Ziel unter 70 %, Große Welle der Heilung unter 60 %, Heilende Woge unter 40 %, mit Totem der Heilungsflut, Führung der Ahnen und Totem der Manaflut auf derselben Leiter. Ein angreifbares Ziel erhält Schaden plus Erdschock.",
-- 8c70a307 English: For levels 1 to 9, and any Shaman who has not chosen a specialization yet;
--     every specialization premade takes over once you pick one. Lightning Bolt to pull from range,
--     Healing Surge when you are low and alone, Primal Strike, Earth Shock, and Lightning Bolt
--     while out of melee range. Keeps Lightning Shield up.
[51] = "Für Stufe 1 bis 9 und jeden Schamanen, der noch keine Spezialisierung gewählt hat; die integrierte Rotation jeder Spezialisierung übernimmt, sobald Sie eine wählen. Blitzschlag zum Ziehen aus der Distanz, Heilende Woge, wenn Sie wenig Gesundheit haben und allein sind, Urtümlicher Schlag, Erdschock und Blitzschlag außerhalb der Nahkampfreichweite. Hält Blitzschlagschild aufrecht.",
}
